var t=`0238-tzatziki`;var r=`world-0238`;var l=`GR`;var o=`southern-europe`;var n=4;var a=38;var s={en:`Tzatziki`,ua:`Дзадзикі`};var u={en:`A traditional Greece dish made with cucumber, greek yogurt, garlic, dill. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: огірок, грецький йогурт, часник, кріп. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:8,i:[[`cucumber`,400,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`greek-yogurt`,440,`g`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,35,`ml`],[`dill`,18,`g`],[`lemon-juice`,25,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 25 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 25 хвилин.`,t:[`rapid-chilling`],m:25,i:[]}];var d={slug:t,id:r,country:`GR`,region:o,servings:4,minutes:38,title:s,text:u,steps:g};export{l as country,d as default,r as id,a as minutes,o as region,n as servings,t as slug,g as steps,u as text,s as title};